function isArmstrong(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)) return {error:'请输入整数'};
  var s=String(n), k=s.length, sum=0, i;
  for(i=0;i<k;i++){ sum+=Math.pow(+s[i],k); }
  return {value:n, isArmstrong:sum===n, digits:k, sum:sum};
}
function armstrongUpTo(limit){
  limit=Math.floor(+limit)||1000;
  if(limit<1||limit>1e6) return {error:'上限须 1–1e6'};
  var out=[], n;
  for(n=0;n<=limit;n++){ var s=String(n),k=s.length,sum=0,i; for(i=0;i<k;i++) sum+=Math.pow(+s[i],k); if(sum===n) out.push(n); }
  return {value:out};
}
var EXPORTS={isArmstrong:isArmstrong, armstrongUpTo:armstrongUpTo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ArmstrongForgePure = EXPORTS; }
